<script setup>
import {Head,Link,usePage} from '@inertiajs/vue3'
import AppLayout from '../../Layouts/AppLayout.vue'
defineProps({student:Object,courses:Array,detail:Object})
const role=usePage().props.auth.user.role.toLowerCase()
const accessLabel=s=>({AVAILABLE:'در دسترس',SCHEDULED:'هنوز در دسترس نیست',LOCKED_SEQUENCE:'قفل ترتیبی',LOCKED_PREREQUISITE:'نیازمند پیش‌نیاز',UNAVAILABLE:'غیرفعال'}[s]||s)
</script>
<template><AppLayout><Head :title="`گزارش ${student.first_name} ${student.last_name}`"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h1 class="text-2xl font-bold">{{student.first_name}} {{student.last_name}}</h1><p class="text-slate-500">{{student.mobile}}</p><div class="mt-5 grid gap-3 md:grid-cols-2"><Link v-for="course in courses" :key="course.id" :href="`/${role}/reports/students/${student.id}?course=${course.id}`" class="rounded-xl border p-4"><div class="flex justify-between"><strong>{{course.title}}</strong><span>{{course.percent}}٪</span></div><div class="mt-2 h-2 rounded bg-slate-200"><div class="h-2 rounded bg-teal-600" :style="{width:course.percent+'%'}"></div></div><small>{{course.completed_lessons}} از {{course.total_lessons}} درس</small></Link></div><p v-if="!courses.length" class="mt-4">ثبت‌نام مجازی برای نمایش وجود ندارد.</p></section>
<template v-if="detail"><section class="rounded-2xl border bg-white p-5"><h2 class="text-xl font-bold">{{detail.course.title}}</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-slate-50 p-3">تکالیف: {{detail.assignments.submitted}} ارسال / {{detail.assignments.not_submitted}} ارسال‌نشده / {{detail.assignments.late}} دیرهنگام</div><div class="rounded-xl bg-slate-50 p-3">پرسش‌ها: {{detail.questions.open}} باز / {{detail.questions.answered}} پاسخ‌داده / {{detail.questions.resolved}} حل‌شده</div></div></section><section class="space-y-3"><article v-for="lesson in detail.lessons" :key="lesson.id" class="rounded-2xl border bg-white p-5"><p class="text-xs text-slate-500">{{lesson.section||'بدون بخش'}}</p><div class="flex flex-wrap justify-between gap-2"><h3 class="font-bold">{{lesson.title}}</h3><span>{{accessLabel(lesson.access.state)}} — {{lesson.state}}</span></div><div v-for="video in lesson.videos" :key="video.id" class="mt-3 rounded-xl bg-slate-50 p-3"><div class="flex justify-between"><span>{{video.title}}</span><strong>{{video.percent}}٪</strong></div><p class="text-xs">{{video.watched_seconds}} از {{video.duration_seconds||0}} ثانیه دیده شده <span v-if="video.last_viewed_at">— {{new Date(video.last_viewed_at).toLocaleString('fa-IR')}}</span></p></div><p v-if="!lesson.videos.length" class="mt-2 text-sm text-slate-500">این درس ویدیوی مرتبط ندارد.</p></article></section></template></div></AppLayout></template>
